package com.nimbusbill.customer.service;
import com.nimbusbill.customer.exception.ResourceNotFoundException; import com.nimbusbill.customer.repository.AppUserRepository; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import java.util.UUID;
@Service public class CustomerAccessService{private final AppUserRepository users;public CustomerAccessService(AppUserRepository u){users=u;}public boolean isAdmin(Authentication auth){return auth==null||auth.getAuthorities().stream().anyMatch(a->a.getAuthority().equals("ROLE_ADMIN"));}public void require(Authentication auth,UUID customerId){if(isAdmin(auth))return;var user=users.findByEmailIgnoreCase(auth.getName()).orElseThrow(()->new ResourceNotFoundException("Portal user profile not found"));if(customerId==null)throw new AccessDeniedException("Select a customer for a scoped query");if(!"ACTIVE".equals(user.getStatus()))throw new AccessDeniedException("User is not active");if(!user.getCustomerIds().isEmpty()&&!user.getCustomerIds().contains(customerId))throw new AccessDeniedException("Customer is outside your access scope");}}
